modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.OpAmps.Integrator;
end Baseline;
model FINDING00831
  extends Modelica.Electrical.Analog.Examples.OpAmps.Integrator(f=0);
end FINDING00831;
model FINDING00828
  extends Modelica.Electrical.Analog.Examples.OpAmps.Integrator(integrator(R=0));
end FINDING00828;
model FINDING00833
  extends Modelica.Electrical.Analog.Examples.OpAmps.Integrator(integrator(k=0));
end FINDING00833;
model FinalFINDING00831
  extends Modelica.Electrical.Analog.Examples.OpAmps.Integrator(final f=0);
end FinalFINDING00831;
model FinalFINDING00828
  extends Modelica.Electrical.Analog.Examples.OpAmps.Integrator(integrator(final R=0));
end FinalFINDING00828;
model FinalFINDING00833
  extends Modelica.Electrical.Analog.Examples.OpAmps.Integrator(integrator(final k=0));
end FinalFINDING00833;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00831\n");
simulate(FINDING00831, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00828\n");
simulate(FINDING00828, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00833\n");
simulate(FINDING00833, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00831\n");
simulate(FinalFINDING00831, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00828\n");
simulate(FinalFINDING00828, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00833\n");
simulate(FinalFINDING00833, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE FINDING00831\n");
system("./Baseline -override f=0 -r=FINDING00831_override.csv");
print("AUDIT_OVERRIDE FINDING00828\n");
system("./Baseline -override integrator.R=0 -r=FINDING00828_override.csv");
print("AUDIT_OVERRIDE FINDING00833\n");
system("./Baseline -override integrator.k=0 -r=FINDING00833_override.csv");
